import csv, os, datetime as dt, html
K='/home/user/beateristapp-/kit-divulgacao'
FONT=K+'/pagina-de-vendas/fonts'
rows=list(csv.reader(open(K+'/textos/calendario.csv',encoding='utf-8-sig')))[1:]
wd=['seg','ter','qua','qui','sex','sáb','dom']
def thumb(a):
    p=os.path.join(K,a)
    if os.path.isfile(p) and p.endswith(('.jpg','.png')): return f'<img class="th" src="file://{p}">'
    return ''
def cal(sel):
    out='<table class="cal"><tr><th>quando</th><th>canal</th><th>o que postar</th><th>arte</th></tr>'
    for r in rows:
        if not sel(r[0]): continue
        d=dt.date.fromisoformat(r[0]); 
        out+=f'<tr><td><b>{wd[d.weekday()]} {d:%d/%m}</b><br>{r[1]}</td><td>{html.escape(r[2])}<br><small>{html.escape(r[7])}</small></td><td><b>{html.escape(r[5])}</b><br><small>{html.escape(r[6])}</small></td><td>{thumb(r[4])}<small class="fn">{html.escape(os.path.basename(r[4]))}</small></td></tr>'
    return out+'</table>'
